import json
values = [2, 4, 6]
def classify(number):
    if number > 0:
        return "positive"
    if number < 0:
        return "negative"
    return "zero"
print(json.dumps({"slice": values[1:], "range": list(range(1, 6, 2)), "labels": [classify(x) for x in [-1, 0, 1]]}, separators=(",", ":")))

